<?php include '_header.php';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id'];$status=$_POST['status'];$st=$conn->prepare('UPDATE orders SET status=? WHERE id=?');$st->bind_param('si',$status,$id);$st->execute();}?><h1>Manajemen Pesanan</h1><div class="panel table-wrap"><table class="table"><tr><th>ID</th><th>Pelanggan</th><th>Total</th><th>Alamat</th><th>Status</th></tr><?php $r=$conn->query('SELECT o.*,u.name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC');while($o=$r->fetch_assoc()):?><tr><td>#<?=$o['id']?></td><td><?=htmlspecialchars($o['name'])?></td><td><?=rupiah($o['grand_total'])?></td><td><?=htmlspecialchars($o['shipping_address'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status" onchange="this.form.submit()"><?php foreach(['Pending','Diproses','Dikirim','Selesai','Dibatalkan'] as $s):?><option <?=$o['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></form></td></tr><?php endwhile;?></table></div><?php include '_footer.php';?>
